import{_ as n,o as s,c as i,ag as r,j as t,a as o,t as l}from"./chunks/framework.qXLDknWC.js";const b=JSON.parse(`{"title":"What's New","description":"","frontmatter":{},"headers":[],"relativePath":"whats-new.md","filePath":"whats-new.md"}`),d={name:"whats-new.md"};function c(a,e,u,h,p,g){return s(),i("div",null,[e[7]||(e[7]=r('<h1 id="what-s-new" tabindex="-1">What&#39;s New <a class="header-anchor" href="#what-s-new" aria-label="Permalink to &quot;What&#39;s New&quot;">​</a></h1><p>Quick overview of recent updates to CharacterVault.</p><hr><h2 id="july-2026" tabindex="-1">July 2026 <a class="header-anchor" href="#july-2026" aria-label="Permalink to &quot;July 2026&quot;">​</a></h2><h3 id="larger-context-windows-smarter-ai-budgeting" tabindex="-1">Larger Context Windows &amp; Smarter AI Budgeting <a class="header-anchor" href="#larger-context-windows-smarter-ai-budgeting" aria-label="Permalink to &quot;Larger Context Windows &amp; Smarter AI Budgeting&quot;">​</a></h3><p>AI work with big cards is much more reliable. You can raise the context window far past the old 128K cap, and large lorebooks actually make it into the request.</p><ul><li><strong>Up to 1M context</strong> — <strong>Settings → Sampler → Context Length</strong> includes 256K, 512K, and 1M presets, plus <strong>Custom…</strong> for any value from 4K to 1M</li><li><strong>Lorebook &amp; greetings fill the window</strong> — Selected lorebook entries (and long greeting lists) are packed in piece by piece so you get as much context as the budget allows, instead of almost none</li><li><strong>Safer requests</strong> — CharacterVault is more careful about staying under your Context Length and Max Tokens, which cuts down on “prompt too long” errors from providers</li></ul><p><a href="/CharacterVault/docs/configuration/sampler-settings">Sampler settings →</a><br><a href="/CharacterVault/docs/features/ai-context">AI Context panel →</a></p><hr><h3 id="vault-library-upgrades" tabindex="-1">Vault Library Upgrades <a class="header-anchor" href="#vault-library-upgrades" aria-label="Permalink to &quot;Vault Library Upgrades&quot;">​</a></h3><p>The home library is built for bigger collections.</p><ul><li><strong>Backup</strong> — Download a ZIP of every character (PNG when there is an image, JSON otherwise)</li><li><strong>Bulk import</strong> — Import many cards at once, including <strong>drag and drop</strong> onto the library</li><li><strong>Sort</strong> — Switch between <strong>Name</strong> and <strong>Recent</strong> (preference is remembered)</li><li><strong>Search</strong> — Find cards by <strong>name or tags</strong></li><li><strong>Token estimates</strong> — Each card shows <strong>active / total</strong> estimates; hover for exact counts</li><li><strong>Quick export</strong> — PNG or JSON from the card actions without opening the editor</li></ul><p><a href="/CharacterVault/docs/features/vault-organization">Vault organization →</a><br><a href="/CharacterVault/docs/features/import-export">Import &amp; export →</a></p><hr><h3 id="smaller-improvements" tabindex="-1">Smaller Improvements <a class="header-anchor" href="#smaller-improvements" aria-label="Permalink to &quot;Smaller Improvements&quot;">​</a></h3><ul><li><strong>API key field</strong> — Less likely to trigger browser password-manager prompts when pasting a key in AI settings</li></ul><hr><h2 id="june-2026" tabindex="-1">June 2026 <a class="header-anchor" href="#june-2026" aria-label="Permalink to &quot;June 2026&quot;">​</a></h2><h3 id="in-editor-spellcheck" tabindex="-1">In-Editor Spellcheck <a class="header-anchor" href="#in-editor-spellcheck" aria-label="Permalink to &quot;In-Editor Spellcheck&quot;">​</a></h3><p>A Hunspell-backed spellchecker — the same engine LibreOffice uses — now runs inside the character editor. Misspelled words get a wavy-red underline; hover one to see quick-fix suggestions, <strong>Ignore word</strong>, or <strong>Add to dictionary</strong>.</p>',20)),t("ul",null,[e[3]||(e[3]=t("li",null,[t("strong",null,"Affix-aware"),o(" — "),t("code",null,"running"),o(", "),t("code",null,"ran"),o(", and "),t("code",null,"runs"),o(" all pass without you whitelisting anything")],-1)),t("li",null,[e[0]||(e[0]=t("strong",null,"Smart ignores",-1)),e[1]||(e[1]=o(" — Code fences, ",-1)),t("code",null,l(a.macro),1),e[2]||(e[2]=o(" placeholders, numbers, URLs/emails, and ALL-CAPS acronyms are skipped automatically",-1))]),e[4]||(e[4]=t("li",null,[t("strong",null,"Personal dictionary & per-user ignore list"),o(" — Add good-but-uncommon words (character names, neologisms) once and they stick across all your cards")],-1)),e[5]||(e[5]=t("li",null,[t("strong",null,"Toggle in Settings"),o(" — Disable in "),t("strong",null,"Settings → Studio → Spellcheck"),o(" if you don't want it")],-1)),e[6]||(e[6]=t("li",null,[t("strong",null,"Offline-friendly"),o(" — The English dictionary is fetched once on first use and cached locally so it works without a connection")],-1))]),e[8]||(e[8]=r('<div class="tip custom-block"><p class="custom-block-title">Performance</p><p>Spellchecking is debounced and viewport-scoped, so even large lorebooks stay responsive.</p></div><p><a href="/CharacterVault/docs/features/editor#spellcheck">Learn more →</a></p><hr><h3 id="nanogpt-sign-in-pkce-with-auto-model-fetch" tabindex="-1">NanoGPT Sign-In (PKCE) with Auto Model Fetch <a class="header-anchor" href="#nanogpt-sign-in-pkce-with-auto-model-fetch" aria-label="Permalink to &quot;NanoGPT Sign-In (PKCE) with Auto Model Fetch&quot;">​</a></h3><p>You can now sign in to NanoGPT directly from <strong>Settings → AI Config</strong> — no need to copy an API key from your dashboard. The flow uses OAuth with PKCE (Proof Key for Code Exchange), so your password never leaves NanoGPT&#39;s site and no client secret is stored in CharacterVault.</p><ul><li><strong>One-click sign-in</strong> — A new <strong>Sign in with NanoGPT</strong> button appears next to the API Key field when the Nano-GPT preset is selected.</li><li><strong>Auto-fetch models</strong> — On successful sign-in, your available models are fetched automatically and the model dropdown is populated for you.</li><li><strong>Per-URL caching</strong> — The auto-fetch uses the same per-base-URL cache as manual fetches, so reopening the settings panel loads instantly.</li></ul><div class="tip custom-block"><p class="custom-block-title">Browser popups must be allowed</p><p>The flow opens a new window/tab to NanoGPT. Allow popups for this site if your browser blocks them.</p></div><div class="warning custom-block"><p class="custom-block-title">Mobile</p><p>Works on Chrome for Android. Other mobile browsers may not relay the auth code back to the app — if sign-in doesn&#39;t complete, paste an API key manually.</p></div><p><a href="/CharacterVault/docs/configuration/ai-setup#sign-in-with-nanogpt-pkce">Learn more →</a></p><hr><h3 id="customizable-section-tabs" tabindex="-1">Customizable Section Tabs <a class="header-anchor" href="#customizable-section-tabs" aria-label="Permalink to &quot;Customizable Section Tabs&quot;">​</a></h3><p>The character editor has 18 section tabs by default — more than most people need. A new <strong>Sections</strong> tab in Settings lets you hide the tabs you don&#39;t use, reorder the rest however you like, and reset to the default order at any time.</p><ul><li><strong>Show or hide</strong> — Toggle any section tab on or off with the eye icon</li><li><strong>Reorder</strong> — Move tabs up and down with arrow buttons</li><li><strong>Reset to Defaults</strong> — Restore the original layout in one click</li><li><strong>Mobile-friendly</strong> — Arrow buttons work great on touchscreens; the mobile dropdown respects your custom order and visibility</li></ul><p><a href="/CharacterVault/docs/configuration/section-layout">Learn more →</a></p><hr><h2 id="may-2026" tabindex="-1">May 2026 <a class="header-anchor" href="#may-2026" aria-label="Permalink to &quot;May 2026&quot;">​</a></h2><h3 id="ai-creation-studio" tabindex="-1">AI Creation Studio <a class="header-anchor" href="#ai-creation-studio" aria-label="Permalink to &quot;AI Creation Studio&quot;">​</a></h3><p>The new <strong>AI Creation Studio</strong> lets you generate complete character cards from scratch using AI. Describe your concept or select from curated tags, and the AI creates a name, description, first message, and example dialogue in one flow.</p><p><strong>Features:</strong></p><ul><li><strong>Write Mode</strong> — Free-form concept descriptions</li><li><strong>Tags Mode</strong> — Visual tag selection across 6 categories (Identity, Personality, Role, Genre, Tone, Appearance)</li><li><strong>Feeling Lucky</strong> — Random tag generation with visual vortex animation</li><li><strong>Live Preview</strong> — Edit generated fields in real-time</li><li><strong>Field Regeneration</strong> — Retry or regenerate individual fields</li></ul><p><a href="/CharacterVault/docs/features/ai-creation-studio">Learn more →</a></p><hr><h3 id="model-caching-in-settings" tabindex="-1">Model Caching in Settings <a class="header-anchor" href="#model-caching-in-settings" aria-label="Permalink to &quot;Model Caching in Settings&quot;">​</a></h3><p>The <strong>Character Settings</strong> panel now caches available AI models and providers, so the model list loads instantly on repeat visits. No more waiting for your model provider to respond every time you switch back.</p><p><a href="/CharacterVault/docs/configuration/ai-setup">Configure your AI provider →</a></p><hr><h3 id="response-performance-stats" tabindex="-1">Response Performance Stats <a class="header-anchor" href="#response-performance-stats" aria-label="Permalink to &quot;Response Performance Stats&quot;">​</a></h3><p>AI responses now show performance metrics when complete — look for <strong>TTFT</strong> (time to first token) and <strong>T/S</strong> (tokens per second) in the result header. Available in both the <strong>AI Assistant</strong> chat and the <strong>AI Toolbar</strong> result panel.</p><p><a href="/CharacterVault/docs/features/ai-assistant">AI Assistant →</a><br><a href="/CharacterVault/docs/features/editor">Text Editor →</a></p><hr><h3 id="mobile-copy-buttons" tabindex="-1">Mobile Copy Buttons <a class="header-anchor" href="#mobile-copy-buttons" aria-label="Permalink to &quot;Mobile Copy Buttons&quot;">​</a></h3><p>The copy button on chat messages now appears on mobile devices, so you can quickly grab AI-generated text from your phone or tablet.</p><hr><h3 id="adjusted-sampler-ranges" tabindex="-1">Adjusted Sampler Ranges <a class="header-anchor" href="#adjusted-sampler-ranges" aria-label="Permalink to &quot;Adjusted Sampler Ranges&quot;">​</a></h3><p>The character sampler parameter sliders (temperature, top-p, etc.) now have a wider and more sensible range, giving you finer control over your generations.</p><p><a href="/CharacterVault/docs/configuration/sampler-settings">Sampler Settings →</a></p><hr><h2 id="april-2026" tabindex="-1">April 2026 <a class="header-anchor" href="#april-2026" aria-label="Permalink to &quot;April 2026&quot;">​</a></h2><h3 id="lorebook-import-export" tabindex="-1">Lorebook Import &amp; Export <a class="header-anchor" href="#lorebook-import-export" aria-label="Permalink to &quot;Lorebook Import &amp; Export&quot;">​</a></h3><p>You can now import and export lorebooks independently from the <strong>Lorebook Editor</strong>.</p><ul><li><strong>Export</strong> — Save your character&#39;s lorebook as a JSON file for sharing or backup</li><li><strong>Import</strong> — Bring in lorebook data from JSON files exported by SillyTavern and other tools</li></ul><p><a href="/CharacterVault/docs/features/lorebook-editor#import--export">Learn more →</a></p><hr><h3 id="multi-line-input-in-ai-panels" tabindex="-1">Multi-line Input in AI Panels <a class="header-anchor" href="#multi-line-input-in-ai-panels" aria-label="Permalink to &quot;Multi-line Input in AI Panels&quot;">​</a></h3><p>The AI chat input and toolbar custom instructions now support multi-line text. Press <strong>Shift+Enter</strong> to insert line breaks when writing longer prompts or detailed instructions.</p><ul><li><strong>AI Assistant chat</strong> — Multi-line input for complex queries to Orion</li><li><strong>AI Toolbar</strong> — Multi-line custom instructions for text operations</li></ul><p><a href="/CharacterVault/docs/features/ai-assistant">AI Assistant →</a><br><a href="/CharacterVault/docs/features/editor">Text Editor →</a></p><hr><h3 id="smaller-improvements-1" tabindex="-1">Smaller Improvements <a class="header-anchor" href="#smaller-improvements-1" aria-label="Permalink to &quot;Smaller Improvements&quot;">​</a></h3><ul><li><strong>Lorebook editor</strong> — Empty character books are filtered out during export</li><li><strong>History modal</strong> — Prevented content flash during modal entrance</li><li><strong>Character images</strong> — Implemented content-addressed storage for deduplication</li><li><strong>Lorebook UI</strong> — Swapped name and comment fields to match SillyTavern convention</li></ul><hr><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/changelog">Full Changelog</a></li><li><a href="/CharacterVault/docs/getting-started/installation">Getting Started</a></li></ul>',53))])}const f=n(d,[["render",c]]);export{b as __pageData,f as default};
